package domain

import (
	"fmt"
	"slices"
	"strings"
	"time"
	"unicode/utf8"
)

// Limits of a Reference Library entry (spec/spec.md §10.1).
const (
	MaxReferenceNameRunes = 100
	MaxReferenceTags      = 10
	MaxReferenceTagRunes  = 30
)

// ReferenceSource says where a Reference Library image came from.
type ReferenceSource string

// Reference sources: generated by the Art Director for a Reference Pack, or uploaded by the user.
const (
	SourceGenerated ReferenceSource = "generated"
	SourceUploaded  ReferenceSource = "uploaded"
)

// ReferenceItem is an image of the Reference Library of a Project (reference_item): an
// asset of type reference with a kind, a name and tags, so that it can be found and reused.
type ReferenceItem struct {
	ID        string
	ProjectID string
	AssetID   string
	Kind      ReferenceKind
	Name      string
	Tags      []string
	Source    ReferenceSource
	// SourceShotID is the Shot the image was generated for ("" for an upload).
	SourceShotID string
	CreatedAt    time.Time
}

// LibraryKinds lists the kinds the Library holds: every kind but the Keyframe, which belongs to
// one Shot.
func LibraryKinds() []ReferenceKind {
	return []ReferenceKind{RefCharacter, RefProduct, RefLocation, RefStyle, RefLighting}
}

// ValidLibraryKind reports whether k can be registered in the Library.
func ValidLibraryKind(k ReferenceKind) bool { return slices.Contains(LibraryKinds(), k) }

// Label is the kind as the user sees it.
func (k ReferenceKind) Label() string {
	switch k {
	case RefCharacter:
		return "Character"
	case RefProduct:
		return "Product"
	case RefLocation:
		return "Location"
	case RefStyle:
		return "Style"
	case RefLighting:
		return "Lighting"
	case RefKeyframe:
		return "Keyframe"
	}
	return string(k)
}

// ParseTags splits the tag input of the form at commas, whitespace and 、, drops empty and repeated
// tags (ignoring case) and checks the limits.
func ParseTags(input string) ([]string, error) {
	fields := strings.FieldsFunc(input, func(r rune) bool {
		return r == ',' || r == '、' || r == '，' || r == ' ' || r == '\t' || r == '\n' || r == '　'
	})
	tags := []string{}
	for _, f := range fields {
		if slices.ContainsFunc(tags, func(t string) bool { return strings.EqualFold(t, f) }) {
			continue
		}
		if utf8.RuneCountInString(f) > MaxReferenceTagRunes {
			return nil, fmt.Errorf("tag %q is longer than %d characters", f, MaxReferenceTagRunes)
		}
		tags = append(tags, f)
	}
	if len(tags) > MaxReferenceTags {
		return nil, fmt.Errorf("more than %d tags", MaxReferenceTags)
	}
	return tags, nil
}

// SameReferenceName compares the names of two references the way the Reference Pack matches them:
// ignoring case and surrounding space.
func SameReferenceName(a, b string) bool {
	return strings.EqualFold(strings.TrimSpace(a), strings.TrimSpace(b))
}
